mapper.select:
SELECT iti.REL_ID as relId, iti.REL_NAME as relName, iti.TRAN_TYPE as tranType, iti.REMARK as remark, iti.TRAN_DATE as tranDate, iti.TRA_SUB_NAME as traSubName, iti.manager_org as managerOrg, SUM(iti.prac_trade_amount) over(partition by rel_id,tran_type,bus_type
,manager_org
) as contractAmount, iti.BUS_TYPE AS tranOverView FROM ins_tra_other iti WHERE iti.STATUS IN ('6','7','10') AND iti.DELFLAG_ = '1' and iti.tran_type is not null and iti.prac_trade_amount is not null and iti.bus_type is not null
and to_char(iti.TRAN_DATE,'YYYY-MM-DD') BETWEEN #{staTime} AND #{endTime}
